<?php header('Content-Type: application/json; charset=utf-8');$provider=$_GET['provider']??'';if(!in_array($provider,['apple','facebook','google'],true)){http_response_code(400);echo json_encode(['ok'=>false,'error'=>'Unsupported provider']);exit;}echo json_encode(['ok'=>false,'provider'=>$provider,'error'=>'Configure the provider OAuth client ID, redirect URI, secret, token validation, and server-side session before enabling production sign-in.']);?>